// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(target != address(0) && target.code.length == 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        bool success;
        vm.prank(c.owner());
        try c.sendMoney(target, amount) { success = true; } catch { success = false; }
        uint256 balanceAfter = address(c).balance;
        bool balanceDecreasedCorrectly;
        if (success) {
            balanceDecreasedCorrectly = (balanceAfter == balanceBefore - amount);
        } else {
            balanceDecreasedCorrectly = (balanceAfter == balanceBefore);
        }
        assertTrue(balanceDecreasedCorrectly);
    }
}
